def f(n):
    return n // 10 + 3 * (n % 10)

def simulate(n, steps):
    for _ in range(steps):
        n = f(n)
    return n

# Test small n
for n in range(1, 100):
    res = simulate(n, 50)
    print(f"n={n}, res={res}")

def f(n):
    return n // 10 + 3 * (n % 10)

def find_cycles(limit):
    visited = {}
    cycles = []
    for i in range(1, limit):
        if i in visited:
            continue
        path = []
        curr = i
        while curr not in visited and curr not in path:
            path.append(curr)
            curr = f(curr)

        if curr in path:
            # Found a cycle
            cycle_start_idx = path.index(curr)
            cycle = path[cycle_start_idx:]
            if cycle not in cycles:
                cycles.append(cycle)

        for p in path:
            visited[p] = True
    return cycles

print(find_cycles(1000))
